Here is a basic implementation of a pendulum swinging simulation using HTML5 canvas and JavaScript. The physics of the pendulum is simulated using the equations of simple harmonic motion.

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Pendulum Simulation</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<input id="initialAngle" type="number" value="45">
<button id="startButton">Start</button>
<canvas id="pendulumCanvas" width="400" height="400"></canvas>

<script>
    let canvas = document.getElementById('pendulumCanvas');
    let ctx = canvas.getContext('2d');
    let initialAngle = Number(document.getElementById('initialAngle').value);
    let gravity = 0.2;
    let friction = 0.01;
    let pendulumLength = 150;
    let mass = 1;
    let angle = initialAngle;
    let velocity = 0;
    let simulationRunning = false;

    function clearCanvas() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
    }

    function drawPendulum() {
        clearCanvas();
        ctx.beginPath();
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 2;

        let pendulumEndX = canvas.width / 2 + pendulumLength * Math.sin(angle);
        let pendulumEndY = canvas.height / 2 - pendulumLength * Math.cos(angle);

        ctx.moveTo(canvas.width / 2, canvas.height / 2);
        ctx.lineTo(pendulumEndX, pendulumEndY);
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(pendulumEndX, pendulumEndY, 5, 0, 2 * Math.PI);
        ctx.fillStyle = 'black';
        ctx.fill();

        ctx.beginPath();
        ctx.arc(canvas.width / 2, canvas.height / 2, 5, 0, 2 * Math.PI);
        ctx.fillStyle = 'black';
        ctx.fill();
    }

    function updatePendulum() {
        if (!simulationRunning) {
            return;
        }

        let acceleration = -gravity / pendulumLength * Math.sin(angle);
        velocity += acceleration;
        angle += velocity;
        velocity *= 1 - friction;

        if (Math.abs(velocity) < 0.01) {
            simulationRunning = false;
        }
    }

    function startSimulation() {
        simulationRunning = true;
        drawPendulum();
    }

    document.getElementById('startButton').addEventListener('click', startSimulation);

    setInterval(() => {
        updatePendulum();
        drawPendulum();
    }, 16); // 16ms = approximately 60fps
</script>
</html>
```

This code creates a simple simulation of a pendulum swinging. The pendulum's angle and velocity are updated every frame based on the laws of simple harmonic motion and the effect of gravity and friction. The simulation runs at approximately 60 frames per second.

