Here is a sample Go AWS Lambda function that deletes EBS Snapshots based on the specified retention policy:
```go
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
	"math"
)

const (
	ec2Region = "your-region" // Update with your region
)

func handler(ctx context.Context, event map[string]interface{}) (interface{}, error) {
	sess, err := session.NewSession(&aws.Config{Region: aws.String(ec2Region)}, nil)
	if err != nil {
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	// Filter EBS Snapshots by tag "backup_type"
	params := &ec2 DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name:  aws.String("tag:backup_type"),
				Values: []*string{
					aws.String("monthly"),
					aws.String("daily"),
					aws.String("weekly"),
					aws.String("yearly"),
				},
			},
		},
	}
	resp, err := ec2Svc.DescribeSnapshots(params)
	if err != nil {
		return nil, err
	}

	// Create a map to store snapshots by tag value
	snapshots := make(map[string][]*ec2.Snapshot)

	for _, snap := range resp.Snapshots {
		tagVals, err := ec2SvcKeyDown(snap, "tag:backup_type")
		if err != nil {
			return nil, err
		}
		if len(tagVals) == 0 {
			// Skip snapshots without the "backup_type" tag
			continue
		}
		for _, val := range tagVals {
			snapshots[val] = append(snapshots[val], snap)
		}
	}

	// Delete snapshots based on retention policy
	for tag, snaps := range snapshots {
		switch tag {
		case "monthly":
			// Keep the last 14 monthly snapshots
			maxAge := int64(14)
			for _, snap := range snaps {
				if len(snaps) <= maxAge {
					break
				}
				deleteSnapshots(&ec2Svc, snap.SnapshotId)
			}
		case "daily":
			// Keep the last 10 daily snapshots
			maxAge := int64(10)
			for _, snap := range snaps {
				if len(snaps) <= maxAge {
					break
				}
				deleteSnapshots(&ec2Svc, snap.SnapshotId)
			}
		case "weekly":
			// Keep the last 4 weekly snapshots
			maxAge := int64(4)
			for _, snap := range snaps {
				if len(snaps) <= maxAge {
					break
				}
				deleteSnapshots(&ec2Svc, snap.SnapshotId)
			}
		case "yearly":
			// Keep only the latest yearly snapshot
			deleteSnapshots(&ec2Svc, snaps[0].SnapshotId)
		}
	}

	return nil, nil
}

func ec2SvcKeyDown(snap *ec2.Snapshot, tagName *string) ([]*string, error) {
	var tagVals []*string
	err := ec2Svc.getTags(&ec2.GetTagsInput{
		Resources: []*string{aws.String(snap.SnapshotId)},
		Tags:      []*ec2.Tag{{Key: tagName}},
	}, &tagVals)
	if err != nil {
		return nil, err
	}
	return tagVals, nil
}

func deleteSnapshots(ec2Svc *ec2.EC2, snapshotId *string) {
	_, err := ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
		SnapshotId: snapshotId,
	})
	if err != nil {
		log.Println(err)
	}
}

func main() {
	theEvent := map[string]interface{}{}
	theContext := context.Background()
	result, err := handler(theContext, theEvent)
	if err != nil {
		fmt.Println(err)
	}
}
```
